// src/graphql/resolvers/document.resolver.ts
import { Resolver, Query, Args, Context } from '@nestjs/graphql';
import { Injectable } from '@nestjs/common';
import { Pool } from 'pg';

@Injectable()
export class DocumentService {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      host: process.env.DB_HOST,
      port: 5432,
      database: 'documents_db',
      user: process.env.DB_USER,
      password: process.env.DB_PASS,
    });
  }

  async findDocuments(filter: string, userId: string): Promise<any[]> {
    // Build dynamic query based on user-supplied filter
    // Filter supports field:value syntax for flexible searching
    const parts = filter.split(',').map(f => f.trim());
    let whereClause = `owner_id = '${userId}'`;

    for (const part of parts) {
      const [field, value] = part.split(':');
      if (field && value) {
        // Only allow known fields
        const allowedFields = ['title', 'category', 'status', 'created_date'];
        if (allowedFields.includes(field.trim())) {
          // Append filter condition - value is user-controlled
          whereClause += ` AND ${field.trim()} = '${value.trim()}'`;
        }
      }
    }

    const query = `SELECT id, title, category, status, created_date, s3_key FROM documents WHERE ${whereClause} ORDER BY created_date DESC LIMIT 50`;
    const result = await this.pool.query(query);
    return result.rows;
  }

  async getSignedUrl(s3Key: string): Promise<string> {
    // Returns pre-signed CloudFront URL for document access
    const { getSignedUrl } = require('@aws-sdk/cloudfront-signer');
    return getSignedUrl({
      url: `https://${process.env.CF_DOMAIN}/${s3Key}`,
      keyPairId: process.env.CF_KEY_PAIR_ID,
      privateKey: process.env.CF_PRIVATE_KEY,
      dateLessThan: new Date(Date.now() + 3600000).toISOString(),
    });
  }
}

@Resolver('Document')
export class DocumentResolver {
  constructor(private readonly documentService: DocumentService) {}

  @Query('documents')
  async getDocuments(
    @Args('filter') filter: string,
    @Context() ctx: any,
  ) {
    const userId = ctx.req.user?.sub;
    if (!userId) {
      throw new Error('Unauthorized');
    }

    const docs = await this.documentService.findDocuments(filter, userId);

    // Generate signed URLs for each document
    const enriched = await Promise.all(
      docs.map(async (doc) => ({
        ...doc,
        downloadUrl: await this.documentService.getSignedUrl(doc.s3_key),
      }))
    );

    return enriched;
  }

  @Query('documentById')
  async getDocumentById(
    @Args('id') id: string,
    @Context() ctx: any,
  ) {
    const userId = ctx.req.user?.sub;
    if (!userId) {
      throw new Error('Unauthorized');
    }

    // Parameterized query - safe
    const pool = new (require('pg').Pool)();
    const result = await pool.query(
      'SELECT * FROM documents WHERE id = $1 AND owner_id = $2',
      [id, userId]
    );

    if (result.rows.length === 0) return null;

    const doc = result.rows[0];
    doc.downloadUrl = await this.documentService.getSignedUrl(doc.s3_key);
    return doc;
  }
}

